mapper.select:
SELECT

FROM foods f
LEFT JOIN pois p ON p.id = f.poi_id
LEFT JOIN spots s ON s.id = p.spot_id
LEFT JOIN pois current_p ON current_p.id = #{spotId}
LEFT JOIN spots current_s ON current_s.id = #{spotId}
WHERE f.status = 1

    AND f.cuisine_code = #{cuisine}


    AND f.price_level = #{priceLevel}


    AND f.poi_id = #{poiId}


    AND (


            OR f.poi_id = #{spotId}
            OR p.spot_id = #{spotId}
            OR p.spot_id = current_p.spot_id
            OR p.place_group_id = current_p.place_group_id
            OR p.spot_id = current_s.id
            OR p.place_group_id = current_s.legacy_place_group_id


            OR p.place_group_id = #{placeGroupId}


    )



        ORDER BY f.hotness DESC, f.rating DESC, f.id ASC


        ORDER BY distance ASC, f.rating DESC, f.hotness DESC, f.id ASC


        ORDER BY f.rating DESC, f.hotness DESC, f.id ASC


LIMIT #{limit}

mapper.update:
UPDATE foods
SET rating = (
  SELECT ROUND(AVG(fr.rating), 1)
  FROM food_reviews fr
  WHERE fr.food_id = #{foodId}
    AND fr.rating IS NOT NULL
)
WHERE id = #{foodId}
  AND EXISTS (
    SELECT 1
    FROM food_reviews fr
    WHERE fr.food_id = #{foodId}
      AND fr.rating IS NOT NULL
  )
